//go:build s390x

package floats

import "unsafe"

// The s390x kernel of CMulTo (cmulto.go), generated by go-asmgen (cmulto_s390x_gen.go)
// into cmulto_s390x.s: the vector facility (the z13 baseline, as the other s390x
// kernels), one complex number per vector register, four per step and the last two and
// one in the same call. go:noescape.
//
//go:noescape
func cmulToVX(dst, a, b *float64, n int)

// cmulToVXMin is the length from which the kernel beats the portable loop: measured on
// z17 (linuxone, 2026-11-22), the call and the set-up cost about 6 ns, which the loop
// does not pay, and the kernel saves about 0.5 ns a number; below it the loop wins.
const cmulToVXMin = 20

func cmulTo(dst, a, b []complex128) {
	if len(dst) >= cmulToVXMin {
		cmulToVX(f64ptr(&dst[0]), f64ptr(&a[0]), f64ptr(&b[0]), len(dst))
		return
	}
	cmulToTail(dst, a, b, 0)
}

func f64ptr(p *complex128) *float64 { return (*float64)(unsafe.Pointer(p)) }
